use dioxus::prelude::*;
use crate::politics::data::person::{Background::*, BureaucraticType::*, MilitaryBranch::*};

#[derive(Clone, PartialEq)]
pub struct Portraiture {
    pub sketch: Asset,
    pub normal: Asset,
    pub source: &'static str,
}

#[derive(Clone, PartialEq)]
pub struct Name {
    pub full: &'static str,
    pub last: &'static str,
}

#[derive(Clone, PartialEq)]
pub struct Appointment {
    pub term: (u32, u32),
    pub name: &'static str,
    pub subs: &'static [Appointment],
}

#[derive(Clone, PartialEq)]
enum BureaucraticType {
    Diplomatic,
    Domestic
}

#[derive(Clone, PartialEq)]
enum MilitaryBranch {
    AirForce,
    Army,
    MarineCorps,
    Navy,
    SpaceForce
}

#[derive(Clone, PartialEq)]
pub enum Background {
    Aristocrat,
    Bureaucrat(BureaucraticType),
    LegalPractitioner,
    Veteran(MilitaryBranch),
    Politician,
    Scholar,

    Sovereign,
    HeadOfBureaucracy(BureaucraticType),
    HeadOfMilitary(MilitaryBranch),
    HeadOfState
}


#[derive(Clone, PartialEq)]
